(5288946, 769462, 88822, '<td valign="top">Nice portrait.  A little more definition in contrast would probably help.  The right side is a little over exposed.</td>', 'Nice portrait.  A little more definition in contrast would probably help.  The right side is a little over exposed.', '2009-03-04 15:02:48.000000', NULL, 1),
(5288947, 769977, 88822, '<td valign="top">Nice capture.</td>', 'Nice capture.', '2009-03-04 15:02:49.000000', NULL, 1),
