(5288957, 770109, 88822, '<td valign="top">NIce lighting and composition.  I would have given this a little more room at the bottom of the image.</td>', 'NIce lighting and composition.  I would have given this a little more room at the bottom of the image.', '2009-03-04 15:03:35.000000', NULL, 1),
(5288958, 769780, 88822, '<td valign="top">Nice colors.  Well done shot.</td>', 'Nice colors.  Well done shot.', '2009-03-04 15:03:36.000000', NULL, 1),
(5288959, 769386, 88822, '<td valign="top">Personally the eye is a little distracting.  If all possible I would have shown the whole horn.  Viewing it like this takes away from the shot.</td>', 'Personally the eye is a little distracting.  If all possible I would have shown the whole horn.  Viewing it like this takes away from the shot.', '2009-03-04 15:03:37.000000', NULL, 1),
(5288960, 769787, 88822, '<td valign="top">Interesting design, but over all a little flat (need more contrast), and having the skin inside a glass container does not help here.</td>', 'Interesting design, but over all a little flat (need more contrast), and having the skin inside a glass container does not help here.', '2009-03-04 15:03:38.000000', NULL, 1),
(5288961, 769636, 88822, '<td valign="top">A little overexposed backside of the elephant, but interesting idea.</td>', 'A little overexposed backside of the elephant, but interesting idea.', '2009-03-04 15:03:39.000000', NULL, 1),
(5288962, 769953, 88822, '<td valign="top">Light a little harsh in some spots, and not enough in others.  Too much dark space around the apple.  Personally I would crop it a bit tighter.</td>', 'Light a little harsh in some spots, and not enough in others.  Too much dark space around the apple.  Personally I would crop it a bit tighter.', '2009-03-04 15:03:41.000000', NULL, 1),
(5288963, 769739, 88822, '<td valign="top">Good capture, but the focus in on the hands, and not the face where it should be.  I like the angle though.</td>', 'Good capture, but the focus in on the hands, and not the face where it should be.  I like the angle though.', '2009-03-04 15:03:42.000000', NULL, 1),
