(5289130, 769496, 2612, '<td valign="top">Fun image and an interesting interpretation of ''skin.''</td>', 'Fun image and an interesting interpretation of ''skin.''', '2009-03-04 16:14:36.000000', NULL, 1),
(5289137, 769374, 2612, '<td valign="top">Very cool shot! It took me a second to realize a leg was up rather missing, but that''s minor and maybe just my problem. (7)</td>', 'Very cool shot! It took me a second to realize a leg was up rather missing, but that''s minor and maybe just my problem. (7)', '2009-03-04 16:17:30.000000', NULL, 1),
