(5290500, 768447, 92577, '<td valign="top">nice composition - could be sharper -</td>', 'nice composition - could be sharper -', '2009-03-05 06:35:21.000000', NULL, 1),
(5290505, 769739, 92577, '<td valign="top">charming snap but needs to be sharper and because the sharpness is off it will be assumed that the pink cast is probably off as well. (You could argue that its a skin challenge and some of the skin is in focus but if you include a face in an image then you have to get the eyes right first.)I''m sure you''ll want to practise a lot more anyway with such a lovely model!</td>', 'charming snap but needs to be sharper and because the sharpness is off it will be assumed that the pink cast is probably off as well. (You could argue that its a skin challenge and some of the skin is in focus but if you include a face in an image then you have to get the eyes right first.)I''m sure you''ll want to practise a lot more anyway with such a lovely model!', '2009-03-05 06:42:52.000000', NULL, 1),
(5290507, 769972, 92577, '<td valign="top">the lighting could be more interesting - good luck</td>', 'the lighting could be more interesting - good luck', '2009-03-05 06:47:54.000000', NULL, 1),
