(5298813, 769727, 63633, '<td valign="top">Clever take on the challenge. A well done concept image.</td>', 'Clever take on the challenge. A well done concept image.', '2009-03-10 07:04:35.000000', NULL, 1),
(5298814, 770014, 63633, '<td valign="top">Lovely image. Very well composed and excellent clarity and sharpness. The tongue is gorgeous :)</td>', 'Lovely image. Very well composed and excellent clarity and sharpness. The tongue is gorgeous :)', '2009-03-10 07:05:23.000000', NULL, 1),
(5298815, 769827, 63633, '<td valign="top">Lovely image and meets the challenge perfectly. The composition is very strong.</td>', 'Lovely image and meets the challenge perfectly. The composition is very strong.', '2009-03-10 07:06:20.000000', NULL, 1),
(5298816, 770071, 63633, '<td valign="top">I wouldn''t be surprised to see this on the front page. Well composed and I love the border.</td>', 'I wouldn''t be surprised to see this on the front page. Well composed and I love the border.', '2009-03-10 07:07:23.000000', NULL, 1),
(5298817, 770073, 63633, '<td valign="top">So appropriate for the challenge. Love the tonal range - bumping to 8.</td>', 'So appropriate for the challenge. Love the tonal range - bumping to 8.', '2009-03-10 07:08:00.000000', NULL, 1),
(5298818, 769954, 63633, '<td valign="top">So quirky - I love it! Duotone was a good choice.</td>', 'So quirky - I love it! Duotone was a good choice.', '2009-03-10 07:08:32.000000', NULL, 1),
(5298820, 769570, 63633, '<td valign="top">Lovely lighting. He looks quite the personality! :)</td>', 'Lovely lighting. He looks quite the personality! :)', '2009-03-10 07:09:18.000000', NULL, 1),
(5298821, 770016, 63633, '<td valign="top">Good concept shot. I just wish it were a little sharper.</td>', 'Good concept shot. I just wish it were a little sharper.', '2009-03-10 07:09:48.000000', NULL, 1),
(5298822, 769643, 63633, '<td valign="top">Eeek! A very sharp image that evokes a physical response. I''ll bet you won''t get the score this deserves though because people will feel very negative towards the image. Bumping to 7 because I was too harsh with a 6.</td>', 'Eeek! A very sharp image that evokes a physical response. I''ll bet you won''t get the score this deserves though because people will feel very negative towards the image. Bumping to 7 because I was too harsh with a 6.', '2009-03-10 07:11:36.000000', NULL, 1),
(5298825, 769938, 63633, '<td valign="top">I know you! You nicked my TV!  :)</td>', 'I know you! You nicked my TV!  :)', '2009-03-10 07:12:57.000000', NULL, 1),
(5298826, 769496, 63633, '<td valign="top">I was too harsh on this on the first pass - a great image that although doesn''t say "skin" overtly to me uses it as an essential part of the image. Bumping to 7</td>', 'I was too harsh on this on the first pass - a great image that although doesn''t say "skin" overtly to me uses it as an essential part of the image. Bumping to 7', '2009-03-10 07:14:22.000000', NULL, 1),
(5298828, 769939, 63633, '<td valign="top">This is probably obvious to others, but I''ll embarass myself by wondering - what is that pink thing? Love your lighting.</td>', 'This is probably obvious to others, but I''ll embarass myself by wondering - what is that pink thing? Love your lighting.', '2009-03-10 07:15:52.000000', NULL, 1),
(5298829, 769951, 63633, '<td valign="top">I really like this, but I bet that others don''t. A great and fascinating image - bumping.</td>', 'I really like this, but I bet that others don''t. A great and fascinating image - bumping.', '2009-03-10 07:16:56.000000', NULL, 1),
