(5298833, 769366, 63633, '<td valign="top">Love the expression - I bet this photographer is a woman, and that the bloke is her poor husband - the expression just screams "I''m putting up with this, but there better be something in it for me!" <br/> <br/>Good luck! :)</td>', 'Love the expression - I bet this photographer is a woman, and that the bloke is her poor husband - the expression just screams "I''m putting up with this, but there better be something in it for me!"  Good luck! :)', '2009-03-10 07:20:22.000000', NULL, 1),
(5298835, 769779, 63633, '<td valign="top">What beautiful children!  The tonal range in this is great - and I love the way her face and expression leads you to him. Bumping.</td>', 'What beautiful children!  The tonal range in this is great - and I love the way her face and expression leads you to him. Bumping.', '2009-03-10 07:22:11.000000', NULL, 1),
(5298837, 768772, 63633, '<td valign="top">There''s a lovely mood to this - The noise reduction adds to it, whereas I normally hate noise reduction on skin. Strange ghosting around the elbow though.</td>', 'There''s a lovely mood to this - The noise reduction adds to it, whereas I normally hate noise reduction on skin. Strange ghosting around the elbow though.', '2009-03-10 07:23:44.000000', NULL, 1),
(5298839, 770048, 63633, '<td valign="top">This has posthumous ribbon written all over it! After saying that I''ll be wrong now, but I love the quirkiness :)</td>', 'This has posthumous ribbon written all over it! After saying that I''ll be wrong now, but I love the quirkiness :)', '2009-03-10 07:24:48.000000', NULL, 1),
